import mongoose from 'mongoose';

/**
 * A single unit of learning.
 *
 * Lessons are created as lightweight "shells" (just a title) when the course outline
 * is generated. Their full content is generated by the AI the first time someone opens
 * the lesson; then `isEnriched` flips to true and the content is served from the DB.
 *
 * `content` is an ordered array of flexible blocks, e.g.
 *   { type: 'heading', text } | { type: 'paragraph', text } | { type: 'code', language, text }
 *   { type: 'video', query } | { type: 'mcq', question, options, answer, explanation }
 */
const resourceSchema = new mongoose.Schema(
  {
    title: { type: String, required: true, trim: true },
    type: { type: String, trim: true }, // documentation | article | book | course | ...
    url: { type: String, trim: true }, // only when the AI is confident it's a stable official URL
    searchQuery: { type: String, trim: true }, // fallback: we link to a web search instead
  },
  { _id: false },
);

const lessonSchema = new mongoose.Schema(
  {
    title: { type: String, required: true, trim: true, maxlength: 200 },
    module: { type: mongoose.Schema.Types.ObjectId, ref: 'Module', required: true, index: true },
    // Denormalised parent course: lets us check ownership / delete a course's lessons in one query
    course: { type: mongoose.Schema.Types.ObjectId, ref: 'Course', required: true, index: true },
    order: { type: Number, required: true, min: 0 }, // 0-based position within the module

    objectives: [{ type: String, trim: true }],
    keyTopics: [{ type: String, trim: true }],
    content: { type: [mongoose.Schema.Types.Mixed], default: [] }, // empty until enriched
    resources: { type: [resourceSchema], default: [] },
    isEnriched: { type: Boolean, default: false }, // true once the AI has generated the content

    // Hinglish audio narration (created on request). The MP3 itself lives in LessonAudio.
    narration: {
      type: new mongoose.Schema(
        {
          transcript: { type: String, required: true },
          durationSeconds: { type: Number, required: true },
          voice: String,
          generatedAt: { type: Date, default: Date.now },
        },
        { _id: false },
      ),
      default: undefined,
    },
  },
  { timestamps: true },
);

export const Lesson = mongoose.model('Lesson', lessonSchema);
